dashboard.definition:
{
  "title": "Setup",
  "description": "Enable the worker in local/inputs.conf, then place exports in $SPLUNK_HOME/var/lib/training_lens/inbox/. Settings are admin-owned files; see the app README for HR zones, goals, corrections, timezone, roles and privacy.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.table",
      "title": "Latest imports",
      "dataSources": {
        "primary": "ds_0"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.table",
      "title": "Setup checklist",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    }
  },
  "dataSources": {
    "ds_0": {
      "type": "ds.search",
      "name": "Latest imports",
      "options": {
        "query": "index=training_lens sourcetype=training_lens:snapshot earliest=0 latest=+10y | dedup snapshot_id | sort 0 - import_epoch | table import_epoch snapshot_id timezone decode_enabled exact_gps quarantined_streams",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_1": {
      "type": "ds.search",
      "name": "Setup checklist",
      "options": {
        "query": "| makeresults | eval worker=\"Enable script input in local/inputs.conf\", inbox=\"SPLUNK_HOME/var/lib/training_lens/inbox/\", config=\"Admin-managed config.json in the runtime directory\", zones=\"Configure effective-dated custom HR boundaries\", privacy=\"Export zones and 200m endpoint buffers applied; exact GPS off by default\", access=\"Assign athlete role; location role only for optional exact GPS\" | table worker inbox config zones privacy access",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": [
          {
            "label": "All",
            "value": "All"
          },
          {
            "label": "Run",
            "value": "Run"
          },
          {
            "label": "Ride",
            "value": "Ride"
          },
          {
            "label": "Hike",
            "value": "Hike"
          },
          {
            "label": "Alpine Ski",
            "value": "Alpine Ski"
          },
          {
            "label": "Weight Training",
            "value": "Weight Training"
          },
          {
            "label": "Workout",
            "value": "Workout"
          },
          {
            "label": "Walk",
            "value": "Walk"
          },
          {
            "label": "Swim",
            "value": "Swim"
          },
          {
            "label": "Nordic Ski",
            "value": "Nordic Ski"
          },
          {
            "label": "Backcountry Ski",
            "value": "Backcountry Ski"
          },
          {
            "label": "Kayaking",
            "value": "Kayaking"
          }
        ]
      }
    },
    "gear": {
      "type": "input.text",
      "title": "Gear (exact name or All)",
      "options": {
        "token": "gear",
        "defaultValue": "All"
      }
    },
    "quality": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {
        "item": "viz_0",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 300,
          "w": 1200,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "time",
      "sport",
      "gear",
      "quality",
      "units",
      "snapshot"
    ]
  }
}
